            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply backward force to avoid collisions
        fx = -35.0  # Strictly < -34.0 N

        # Vertical control to avoid floor/ceiling
        fy = 60.0 * (ty - actual_y) - 20.0 * vyd + w_comp

        # Wall avoidance: apply lateral force if near wall
        if front < 0.5:
            if up > down:
                fy += 50.0  # Push upward to avoid floor
            else:
                fy -= 50.0  # Push downward to avoid ceiling

        # Transition to HOLD phase when in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Zero forward force to maintain position in exit zone
        fx, fy = 0.0, w_comp

    # Clamp vertical position to avoid floor/ceiling contact (integrated into fy calculation)

    sandbox.apply_agent_force(fx, fy)

import math

ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
WALL_CLEARANCE_Y = 1.5  # Target vertical position to avoid wall #4's y-range

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_steps": 0,
            "stuck_count": 0,
            "nav_phase": False
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    front, up, down = sandbox.get_whisker_readings()

    # Use reported y position directly for vertical control
    actual_y = y

    # Dynamic vertical target based on wall proximity
    if front < 0.3 and x < ACTIVATION_X_MIN:
        ty = WALL_CLEARANCE_Y  # Clear wall #4's vertical range (y=0.0-1.0m)
    else:
        ty = 1.5

    w_comp = _weight_comp(sandbox)

    if state["phase"] == "APPROACH":
        # Vertical control: lift off floor if near wall
        fy = 60.0 * (ty - actual_y) - 20.0 * vyd + w_comp

        # Forward force: reduce when near wall to prevent collision
        if front < 0.3 and x < ACTIVATION_X_MIN:
            fx = 40.0  # Reduced forward force to prevent collision with wall #4
        else:
            fx = 60.0 if x < ACTIVATION_X_MIN else 10.0 * (7.0 - x) - 5.0 * vxd

        # Lateral escape logic when stuck
        if abs(vxd) < 0.1:
            state["stuck_count"] += 1
            if state["stuck_count"] > 10:
                # Apply upward/lateral force to clear wall #4
                if up > down:
                    fy += 50.0  # Push upward to avoid floor
                else:
                    fy -= 50.0  # Push downward to avoid ceiling
        else:
            state["stuck_count"] = 0

        # Transition to UNLOCK when actual position is in activation zone
        if (x >= ACTIVATION_X_MIN) and (front > 0.3) and vxd > 0.1:
            state["phase"] = "UNLOCK"
            state["t"] = 0
            state["unlock_steps"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Strictly enforce Fx < -34.0 N
        fx_cmd = -35.0
        fy_cmd = 60.0 * (ty - actual_y) - 20.0 * vyd + w_comp

        # Maintain vertical position to avoid floor/ceiling
        if actual_y < 0.5:
            fy_cmd += 50.0
        elif actual_y > 2.5:
            fy_cmd -= 50.0

        # Check unlock conditions using physical velocity
        if fx_cmd < BACKWARD_FX_THRESHOLD and spd < BACKWARD_SPEED_MAX:
            state["unlock_steps"] += 1
        else:
            state["unlock_steps"] = 0

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1

        # Transition to ESCAPE after 5 consecutive valid steps
        if state["unlock_steps"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply FORWARD force to progress towards exit (was previously backward)
        fx = 35.0  # Forward force to overcome environmental resistance

        # Vertical control to avoid floor/ceiling
        fy = 60.0 * (ty - actual_y) - 20.0 * vyd + w_comp

        # Wall avoidance: apply lateral force if near wall
        if front < 0.5:
            if up > down:
                fy += 50.0  # Push upward to avoid floor
            else:
                fy -= 50.0  # Push downward to avoid ceiling

        # Transition to HOLD phase when in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Zero forward force to maintain position in exit zone
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)
